import '../i18n';
import {StatusBar} from 'react-native';
import {SafeAreaProvider} from 'react-native-safe-area-context';
import {Color} from '../constants';
import {createNativeStackNavigator} from '@react-navigation/native-stack';
import ETaskNavigation from './ETask';
import {useEffect} from 'react';
import {useNotificationServices} from '../hooks/useNotificationServices';
import {useAppDispatch} from '../hooks/useRedux';
import {commonActions} from '../redux/slices';

const Stack = createNativeStackNavigator();
const AppNavigation = () => {
  const NotificationService = useNotificationServices();
  const dispatch = useAppDispatch();
  const login = async () => {
    let dataLogin = await NotificationService.login();
    dispatch(commonActions.setAccessToken(dataLogin.accessToken));
  };
  useEffect(() => {
    login();
  });

  return (
    <SafeAreaProvider>
      <StatusBar
        translucent
        barStyle={'light-content'}
        backgroundColor={Color.Transparent}
      />
      <ETaskNavigation />
    </SafeAreaProvider>
  );
};

export default AppNavigation;
