import {Text, View} from 'react-native';
import TextCM from '../../../../../components/Text';

import RenderHtml from 'react-native-render-html';
import {useTranslation} from 'react-i18next';
import {TaskHistoryEntry} from '../../../../../../model/interface/dashboard.interface';
type Props = {
  taskHistory: TaskHistoryEntry;
};
const CurrentActionDetail = ({taskHistory}: Props) => {
  const {t} = useTranslation();
  function formatDateTime(input: string): string {
    const date = new Date(input);
    const pad = (num: number) => num.toString().padStart(2, '0');
    const day = pad(date.getDate());
    const month = pad(date.getMonth() + 1);
    const year = date.getFullYear();
    const hours = pad(date.getHours());
    const minutes = pad(date.getMinutes());
    const seconds = pad(date.getSeconds());

    return `${day}/${month}/${year} ${hours}:${minutes}:${seconds}`;
  }
  let oldValue = '',
    newValue = '';
  if (taskHistory.actionCode === 'CHG_TSK') {
    if (taskHistory.param.oldStatus === 'custom') {
      oldValue = taskHistory.param.oldStatus;
    } else {
      oldValue = t('HM.board.status-' + taskHistory.param.oldStatus);
    }

    if (taskHistory.param.newStatus === 'custom') {
      newValue = taskHistory.param.newStatus;
    } else {
      newValue = t('HM.board.status-' + taskHistory.param.newStatus);
    }
  }
  const createdBy =
    taskHistory.createdBy === 'Nhatpm6' ? 'you' : taskHistory.createdBy;

  return (
    <View style={{padding: 8}}>
      <TextCM>
        <RenderHtml
          source={{
            html: t(`HM.private.${taskHistory.actionCode}`, {
              oldValue: oldValue,
              newValue: newValue,
              createdBy: createdBy,
              name: taskHistory.taskName,
              style: stylesHTML.RED_BOLD,
            }),
          }}
        />
      </TextCM>
      <Text style={styles.timestamp}>
        {formatDateTime(taskHistory.createdDate)}
      </Text>
    </View>
  );
};

export default CurrentActionDetail;

import {StyleSheet} from 'react-native';
import {stylesHTML} from './helper';

const styles = StyleSheet.create({
  timestamp: {
    fontSize: 12,
    color: '#757575',
    textAlign: 'right',
  },
});
