import {Dimensions, ScrollView, Text, View} from 'react-native';
import TextCM from '../../../components/Text';
import {PieChart} from 'react-native-gifted-charts';
import {styles} from './styles';
import {StatusGroup} from '../../../../model/interface/dashboard.interface';
import {useTranslation} from 'react-i18next';
import {Font} from '../../../../constants';
type Props = {
  status: StatusGroup[];
};

const DashboardPieChart = ({status}: Props) => {
  const {t} = useTranslation();
  const screenWidth = Dimensions.get('window').width;
  const ChartColor: {[key: string]: string} = {
    todo: '#00A3FF',
    processing: '#FF69B4',
    approved: '#943CDD',
    completed: '#90EE90',
  };
  const transformData = (status: StatusGroup[]) => {
    const dataFiltered = status.map(item => {
      const color = ChartColor[item.status];
      const value = ['todo', 'processing', 'approved', 'completed'].includes(
        item.status,
      )
        ? item.taskCount
        : 0;
      return {
        value,
        text: t(`HM.board.status-${item.status}`),
        color: ChartColor[item.status],
        externalLabelComponent: () => (
          <Text key={Math.floor(1).toString()} style={{color}}>
            {value}
          </Text>
        ),
      };
    });
    return dataFiltered;
  };
  let pieData = transformData(status);
  const renderDot = (color: string) => {
    return (
      <View
        style={{
          height: 10,
          width: 10,
          borderRadius: 5,
          backgroundColor: color,
          marginRight: 10,
        }}
      />
    );
  };
  const renderDescription = (pieData: any) => {
    return (
      <ScrollView horizontal style={{flexDirection: 'row', marginTop: 20}}>
        {pieData.map((item: any) => {
          return item.value ? (
            <View
              key={item.text}
              style={{
                flexDirection: 'row',
                alignItems: 'center',
                padding: 5,
              }}>
              {renderDot(item.color)}
              <Text></Text>
              <Text
                style={{
                  color: item.color,
                }}>
                {`${item.text}: ${item.value}`}
              </Text>
            </View>
          ) : null;
        })}
      </ScrollView>
    );
  };
  return (
    <View style={styles.container}>
      <TextCM style={{fontSize: 18, fontFamily: Font.InterBold700}}>
        Tỉ lệ task theo trạng thái
      </TextCM>
      <View
        style={{
          width: screenWidth, // Chiều rộng bằng màn hình
          height: screenWidth - 40, // Chiều cao bằng màn hình để tạo hình vuông
          justifyContent: 'center', // Căn giữa theo chiều dọc
          alignItems: 'center', // Căn giữa theo chiều ngang
          backgroundColor: '#fff', // Nền trắng (có thể thay đổi tùy ý)
          overflow: 'hidden',
        }}>
        {/* <TextCM>Biểu đồ 2</TextCM> */}
        <PieChart
          data={pieData}
          // showText={true}
          textColor={'black'}
          // labelsPosition={'outward'}
          showTooltip={true}
          // showValuesAsTooltipText={true}
          // semiCircle={true}
          // showText
          showExternalLabels={true}
          extraRadius={1000}
          shadow={true}
          focusedPieIndex={0}
          labelLineConfig={{
            //   color: 'black',
            labelComponentHeight: -20,
            //   labelComponentWidth: 20,
            //   avoidOverlappingOfLabels: false,
            // tailLength: 0,
            //   thickness: 1,
          }}
          // externalLabelComponent={(a, b) => {
          //   //   console.log({a, b});
          //   //   console.log(a?.externalLabelComponent);
          //   //   console.log(`${a?.text}: ${a?.value}`);
          //   return ;
          // }}
        />
      </View>
      {renderDescription(pieData)}
    </View>
  );
};

export default DashboardPieChart;
